    ('00000000-0000-0000-0000-000000000401', '{"en-US": "Weekly security summary", "pt-BR": "Resumo semanal de segurança"}'::jsonb, 'SUMMARY', NULL, '2026-10-05', '2026-10-11', '2026-10-12T06:00:00Z', 'SCHEDULE', 'READY', '{"summary": {"en-US": "Remediation outpaced new findings for the fourth week in a row. 14 vulnerabilities were detected and 11 were fixed, leaving 7 open, 2 of them critical. Both critical findings come from outdated dependencies (Apache Tomcat and Next.js) and have fixed versions available. 92% of findings were resolved within the SLA defined in the organization policies.", "pt-BR": "As correções superaram os novos achados pela quarta semana seguida. Foram detectadas 14 vulnerabilidades e corrigidas 11, restando 7 abertas, 2 delas críticas. Os dois achados críticos vêm de dependências desatualizadas (Apache Tomcat e Next.js) e já têm versões corrigidas disponíveis. 92% dos achados foram resolvidos dentro do SLA definido nas políticas da organização."}, "kpis": {"opened": 14, "fixed": 11, "open": 7, "mttrDays": 6.4, "slaCompliance": 92}, "trend": [{"week": "W34", "opened": 9, "fixed": 4}, {"week": "W35", "opened": 12, "fixed": 7}, {"week": "W36", "opened": 7, "fixed": 9}, {"week": "W37", "opened": 10, "fixed": 8}, {"week": "W38", "opened": 6, "fixed": 10}, {"week": "W39", "opened": 8, "fixed": 6}, {"week": "W40", "opened": 5, "fixed": 9}, {"week": "W41", "opened": 4, "fixed": 7}], "severity": {"critical": 2, "high": 2, "medium": 2, "low": 1}, "topRisks": [{"cve": "CVE-2025-24813", "repository": "payments-api", "cvss": 9.8, "ageDays": 3}, {"cve": "CVE-2025-29927", "repository": "storefront-web", "cvss": 9.1, "ageDays": 1}, {"cve": "CVE-2024-45296", "repository": "storefront-web", "cvss": 7.5, "ageDays": 2}, {"cve": "CVE-2024-38816", "repository": "payments-api", "cvss": 7.5, "ageDays": 2}, {"cve": "CVE-2024-47764", "repository": "backoffice", "cvss": 5.3, "ageDays": 5}], "owasp": [{"id": "A01", "name": "Broken Access Control", "findings": 1}, {"id"